mapper.select:
SELECT benefit_id AS benefitId, category, title, discount_summary AS discountSummary, effective_from AS validFrom, effective_to AS validTo, target_text AS target, description AS content, usage_method AS method, precautions, detail_image_url AS detailImageUrl, source_url AS sourceUrl FROM military_benefit WHERE benefit_context = 'LEAVE' AND active_yn = TRUE AND (effective_from IS NULL OR effective_from <= #{referenceDate}) AND (effective_to IS NULL OR effective_to >= #{referenceDate})
AND category = #{category}
ORDER BY category, display_order, benefit_id
